def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, following the "round half to even" rule (also known as "bankers' rounding").

    :param n: The number to round
    :return: The rounded integer
    """
    if not isinstance(n, (int, float)):
        raise TypeError("Input must be a number")

    if n < 0:
        return -round(-n)
    else:
        return round(n)

