def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        if maxsize is None:
            cache = OrderedDict()
        elif maxsize < 1:
            raise ValueError('maxsize must be a positive integer or None.')
        else:
            cache = OrderedDict()
            def _getitem(key):
                try:
                    return cache[key]
                except KeyError:
                    raise KeyError(f"{key} not in cache")
            def make_cache_hit(key, value):
                cache[key] = value
                cache.move_to_end(key)
                if len(cache) > maxsize:
                    cache.popitem(last=False)

        @wraps(func)
        def wrapper(*args, **kwds):
            if typed:
                key = args, tuple(kwds.items())
            else:
                key = args, frozenset(kwds.items())
            try:
                return cache[key]
            except KeyError:
                result = func(*args, **kwds)
                make_cache_hit(key, result)
                return result

        return wrapper

    return decorator

