def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    if maxsize < 1:
        raise ValueError("maxsize must be greater than 0")

    class LFUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = OrderedDict()
            self.freq = {}
            self.min_freq = 1

        def __call__(self, func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                key = (func, args, tuple(sorted(kwargs.items())))
                if not self.typed:
                    key = key[1:]

                freq_key = (key, time.time())
                if key in self.cache:
                    self._update_freq(freq_key)
                    return self.cache[key][1]
                elif len(self.cache) >= self.maxsize:
                    while len(self.cache) >= self.maxsize:
                        if self.freq[self.min_freq] == []:
                            del self.freq[self.min_freq]
                        key_to_remove = self.cache.popitem(last=False)[0]
                        del self.freq[key_to_remove[1]][0]

                result = func(*args, **kwargs)
                self.cache[key_to_remove] = (freq_key, result)
                self.freq[freq_key] = [key]
                self.min_freq = min(self.min_freq, freq_key[1])
                return result

            return wrapper

        def _update_freq(self, key):
            freq_key, timestamp = key
            freq = self.freq[key[0]]
            index = freq.index(freq_key)
            freq.pop(index)
            if not freq:
                del self.freq[key[0]]
                if self.min_freq == key[1]:
                    self.min_freq += 1
            else:
                self.freq[freq_key] = freq

            new_key = (key[0], time.time())
            self.freq[new_key] = [key]
            return new_key

    return LFUCache(maxsize, typed)()

