def _legacy_mergeOrderings(orderings):
    result = []
    remaining_orderings = orderings[:]

    while remaining_orderings:
        found = False
        for i, ordering in enumerate(remaining_orderings):
            if not result or result[-1] in ordering:
                result.extend(ordering)
                found = True
                remaining_orderings.pop(i)
                break

        if not found:
            raise ValueError("Invalid orderings provided")

    return result

