def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not all(isinstance(cls, type) for cls in classes):
        raise ValueError("All elements in the input list must be class types")

    graph = {cls: set(basecls for basecls in cls.__bases__ if basecls in classes) for cls in classes}
    in_degree = {cls: sum(1 for basecls in bases if basecls in classes) for cls, bases in graph.items()}
    queue = [cls for cls, degree in in_degree.items() if degree == 0]

    result = []
    while queue:
        cls = queue.pop(0)
        result.append(cls)
        for neighbor in graph[cls]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return result

