def formatmany(sql: AnyStr, many_params: Union[Iterable[Mapping[str, Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[str, Any]], List[Sequence[Any]]]]:
    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a string or bytes")

    if not isinstance(many_params, Iterable):
        raise TypeError("many_params must be an iterable")

    formatted_sql = sql
    converted_params = []

    for params in many_params:
        if isinstance(params, Mapping):
            formatted_sql = formatted_sql.replace("?", "%s").replace("%s", "%s")
            converted_params.append(params)
        elif isinstance(params, Sequence):
            formatted_sql = formatted_sql.replace("?", "%s")
            converted_params.append(params)
        else:
            raise TypeError("each element in many_params must be a mapping or sequence")

    return formatted_sql, converted_params

