def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    try:
        magnitude, unit = frequency.split()
        magnitude = int(magnitude)
        if unit.lower() == "seconds":
            return datetime.timedelta(seconds=magnitude)
        elif unit.lower() == "minutes":
            return datetime.timedelta(minutes=magnitude)
        elif unit.lower() == "hours":
            return datetime.timedelta(hours=magnitude)
        elif unit.lower() == "days":
            return datetime.timedelta(days=magnitude)
        elif unit.lower() == "weeks":
            return datetime.timedelta(weeks=magnitude)
        elif unit.lower() == "months":
            return datetime.timedelta(days=magnitude * 30)  # Approximation
        elif unit.lower() == "years":
            return datetime.timedelta(days=magnitude * 365)  # Approximation
        else:
            raise ValueError(f"Unsupported time unit: {unit}")
    except (ValueError, AttributeError):
        raise ValueError(f"Invalid frequency format: {frequency}")

