def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    if overrides is None:
        overrides = {}

    configs = {}
    errors = []
    logger = logging.getLogger(__name__)

    for filename in config_filenames:
        if not os.path.exists(filename):
            logger.error(f"Configuration file {filename} does not exist.")
            errors.append(logging.LogRecord(level=logging.ERROR, pathname=__file__,lineno=0,funcName="load_configurations",msg=f"Configuration file {filename} does not exist.",args=()))
            continue

        try:
            with open(filename, 'r') as file:
                config = json.load(file)
        except json.JSONDecodeError as e:
            logger.error(f"Error decoding JSON from {filename}: {e}")
            errors.append(logging.LogRecord(level=logging.ERROR, pathname=__file__,lineno=0,funcName="load_configurations",msg=f"Error decoding JSON from {filename}: {e}",args=()))
            continue

        resolved_config = resolve_environment_variables(config, resolve_env)
        resolved_config.update(overrides)

        configs[filename] = resolved_config

    return configs, tuple(errors)

