def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if not hist.bins_are_numeric() and make_value is None:
        raise ValueError("Histogram bins must be numeric if no make_value function is provided.")

    if make_value is None:
        make_value = lambda bin_content: bin_content

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'.")

    if len(field_names) != len(hist.get_coordinate_names()):
        raise ValueError("field_names must have the same length as the dimension of the histogram.")

    if scale is None:
        scale = hist.scale is not None

    graph_points = []
    for bin_ in hist.iter_bins():
        bin_content = bin_.content
        value = make_value(bin_content)
        if not isinstance(value, tuple):
            value = (value,)
        coordinate_names = hist.get_coordinate_names()
        coordinates = [getattr(bin_, name) for name in coordinate_names]
        if get_coordinate == "left":
            coordinates = [coord - 0.5 for coord in coordinates]
        elif get_coordinate == "right":
            coordinates = [coord + 0.5 for coord in coordinates]
        elif get_coordinate == "middle":
            coordinates = [coord for coord in coordinates]
        graph_point = tuple(coordinates) + value
        graph_points.append(graph_point)

    if scale:
        graph_scale = hist.scale
    else:
        graph_scale = None

    graph = {
        "points": graph_points,
        "field_names": field_names,
        "scale": graph_scale
    }

    return graph

