def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid('Candidate does not claim to provide the interface')

    implemented_methods = set(iface.names(False))
    implemented_attributes = set(iface.names(True))

    candidate_methods = set(dir(candidate)) - set(dir(object))
    candidate_attributes = set(dir(candidate))

    missing_methods = implemented_methods - candidate_methods
    missing_attributes = implemented_attributes - candidate_attributes

    if missing_methods or missing_attributes:
        errors = []
        if missing_methods:
            errors.append(f'Missing methods: {missing_methods}')
        if missing_attributes:
            errors.append(f'Missing attributes: {missing_attributes}')
        raise zope.interface.Invalid('\n'.join(errors))

    methods_with_wrong_signature = []
    for method in implemented_methods:
        candidate_method = getattr(candidate, method)
        if not callable(candidate_method):
            methods_with_wrong_signature.append(f'{method} is not callable')
            continue
        if not zope.interface.implementsMethod(iface, method, candidate_method):
            methods_with_wrong_signature.append(f'{method} has incorrect signature')

    if methods_with_wrong_signature:
        errors = ['Methods with wrong signature:']
        errors.extend(methods_with_wrong_signature)
        raise zope.interface.Invalid('\n'.join(errors))

    return True

