def find_tags(text: str, replacer: Callable[[str], str] = None) -> Tuple[Set[str], str]:
    tags = set()
    in_code_block = False
    result = ""

    for line in text.split('\n'):
        parts = line.split('<')
        for part in parts:
            if not in_code_block:
                if '>' in part:
                    end_index = part.index('>')
                    tag = part.strip('<> ')
                    tags.add(tag)
                    if replacer:
                        part = part.replace(tag, replacer(tag))
                if '```' in part:
                    in_code_block = not in_code_block
            result += part
            if in_code_block:
                result += '>'

    return tags, result.strip()

