def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if not hasattr(node, 'getchildren'):
        raise ValueError(f"Input must be an XML node with children, but got {type(node)}")

    result = {}
    for child_node in node.getchildren():
        tag_name = child_node.tag
        if tag_name in result:
            raise ValueError(f"Duplicate tag name found: {tag_name}")
        result[tag_name] = child_node

    return result

