def parse_diaspora_webfinger(document: str) -> Dict:
    try:
        # Attempt to parse the document as JSON
        data = json.loads(document)
        if "subject" in data and "links" in data:
            return data
    except json.JSONDecodeError:
        # If JSON parsing fails, try to parse as XRD
        try:
            root = ET.fromstring(document)
            subject = root.find("{http://docs.oasis-open.org/ns/xri/xrd/1.0}Subject")
            links = root.findall("{http://docs.oasis-open.org/ns/xri/xrd/1.0}Link")
            if subject is not None and links:
                result = {"subject": subject.text.strip()}
                links_dict = {}
                for link in links:
                    rel = link.get("rel")
                    href = link.get("href")
                    if rel and href:
                        links_dict[rel] = href
                result["links"] = links_dict
                return result
        except ET.ParseError:
            raise ValueError("The document is not in a valid JSON or XRD format.")
    raise ValueError("The document is not in a valid JSON or XRD format.")

