    """Create a new IniType complex type

    Parameters:
    settings_dirs (list): A list of directory paths where ini files are located.
    spec_option (str): A specification option to filter the ini files.

    Returns:
    list: A list of file names of ini files that match the spec_option.
    """
    if not isinstance(settings_dirs, list):
        raise ValueError("settings_dirs must be a list")
    if not all(isinstance(dir, str) for dir in settings_dirs):
        raise ValueError("All elements in settings_dirs must be strings")
    if not isinstance(spec_option, str):
        raise ValueError("spec_option must be a string")

    matching_files = []
    for dir in settings_dirs:
        try:
            for file_name in os.listdir(dir):
                if file_name.endswith('.ini') and spec_option in file_name:
                    matching_files.append(file_name)
        except FileNotFoundError:
            print(f"Directory {dir} not found")
        except PermissionError:
            print(f"Permission denied for directory {dir}")

    return matching_files

