def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Args:
        parser_dict (dict): The dictionary containing the parsed spec file.

    Returns:
        dict: The updated dictionary after resolving the include dict directive.
    """
    if not isinstance(parser_dict, dict):
        raise ValueError("Invalid input: parser_dict must be a dictionary.")

    if "include" not in parser_dict:
        return parser_dict

    include_dict = parser_dict.pop("include")

    if not isinstance(include_dict, dict):
        raise ValueError("Invalid input: include directive must be a dictionary.")

    for key, value in include_dict.items():
        if key in parser_dict:
            raise ValueError(f"Conflict: key '{key}' already exists in the parser dictionary.")

        parser_dict[key] = value

    return parser_dict

