def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict with arguments
    :return: None
    """
    if not isinstance(parser_name, str) or not isinstance(values_dict, dict):
        raise ValueError("Invalid input types")

    arg_types = {
        'int': int,
        'float': float,
        'bool': lambda val: val.lower() in ['true', '1', 't', 'y', 'yes'],
        'list': lambda val: [item.strip() for item in val.split(',')]
    }

    for key, value in values_dict.items():
        if value.isdigit():
            values_dict[key] = int(value)
        elif value.replace('.', '', 1).isdigit():
            values_dict[key] = float(value)
        elif value.lower() in ['true', 'false', '1', '0']:
            values_dict[key] = value.lower() == 'true' or value == '1'
        elif ',' in value:
            values_dict[key] = [item.strip() for item in value.split(',')]
        else:
            for arg_type, converter in arg_types.items():
                try:
                    values_dict[key] = converter(value)
                    break
                except (ValueError, TypeError):
                    continue

    return None

