def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
        with open(spec_path, 'r') as file:
            spec_data = json.load(file)

        def flatten_dict(data, parent_key='', sep='_'):
            items = {}
            for k, v in data.items():
                new_key = f"{parent_key}{sep}{k}" if parent_key else k
                if isinstance(v, dict):
                    items.update(flatten_dict(v, new_key, sep=sep).items())
                else:
                    items[new_key] = v
            return items

        return flatten_dict(spec_data)

    except FileNotFoundError:
        raise FileNotFoundError(f"Plugin spec file not found at {spec_path}")
    except json.JSONDecodeError:
        raise ValueError(f"Invalid JSON format in the plugin spec file at {spec_path}")
    except Exception as e:
        raise Exception(f"An error occurred while processing the plugin spec file at {spec_path}: {e}")

